import type { Body, BirthInput } from '../types.ts';
import data from './fixtures.json';

export interface ReferenceChart {
  id: string;
  description: string;
  input: BirthInput;
  expectedOffsetMinutes: number;
  utc: string;
  julianDayUt: number;
  bodies: Record<Body, { lon: number; speed: number }>;
  ascendant: number;
  midheaven: number;
  armc: number;
  cusps: { placidus: number[]; porphyry: number[]; wholeSign: number[] };
}

/** Reference charts generated by scripts/gen-fixtures.ts (Swiss Ephemeris). */
export const REFERENCE_CHARTS = data.charts as ReferenceChart[];

/** Deterministic PRNG (mulberry32) for property tests. */
export function seededRandom(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
